@if($shift)<div class="payment-modal" data-payment-modal hidden><div class="payment-dialog"><button class="modal-close" type="button" data-close-payment>×</button><span class="section-kicker">Cobro seguro</span><h2>Registrar pago</h2><p data-payment-label></p><div class="payment-total"><span>Total de la cuenta</span><strong>$<b data-payment-total>0.00</b></strong></div><form method="POST" data-payment-form>@csrf<label>Método de pago<select name="metodo" data-payment-method required><option value="efectivo">Efectivo</option><option value="tarjeta">Tarjeta</option><option value="transferencia">Transferencia</option></select></label><label data-cash-field>Dinero recibido<input type="number" name="recibido" min="0" step="0.01" data-payment-received placeholder="0.00"></label><div class="change-box">Cambio a entregar<strong>$<span data-payment-change>0.00</span></strong></div><button class="button primary" type="submit">Confirmar cobro</button></form></div></div><script>document.addEventListener('DOMContentLoaded',()=>{const modal=document.querySelector('[data-payment-modal]'),form=modal.querySelector('[data-payment-form]'),total=modal.querySelector('[data-payment-total]'),received=modal.querySelector('[data-payment-received]'),change=modal.querySelector('[data-payment-change]'),method=modal.querySelector('[data-payment-method]'),cash=modal.querySelector('[data-cash-field]');const update=()=>{const amount=parseFloat(total.textContent)||0,paid=parseFloat(received.value)||0;change.textContent=Math.max(0,paid-amount).toFixed(2)};document.querySelectorAll('[data-open-payment]').forEach(button=>button.addEventListener('click',()=>{total.textContent=button.dataset.total;modal.querySelector('[data-payment-label]').textContent=button.dataset.label;form.action=`{{ url('/caja/atenciones') }}/${button.dataset.attention}/cobrar`;received.value='';update();modal.hidden=false;received.focus()}));[received,method].forEach(input=>input.addEventListener('input',update));method.addEventListener('change',()=>{cash.hidden=method.value!=='efectivo';received.required=method.value==='efectivo';update()});document.querySelector('[data-close-payment]').addEventListener('click',()=>modal.hidden=true);modal.addEventListener('click',event=>{if(event.target===modal)modal.hidden=true})});</script>@endif
